import sys
from typing import Optional

sys.setrecursionlimit(200000)


class SyntaxError_(Exception):
    pass


RESERVED = {
    "fun", "let", "rec", "in", "if", "then", "else", "true", "false"
}

NAME_START = set("abcdefghijklmnopqrstuvwxyz_")
NAME_CONT = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'")


class Token:
    def __init__(self, kind: str, text: str):
        self.kind = kind
        self.text = text

    def __repr__(self):
        return f"Token({self.kind!r}, {self.text!r})"


def tokenize(src: str) -> list[Token]:
    i = 0
    n = len(src)
    tokens = []

    def is_whitespace(ch: str) -> bool:
        return ch == " " or ch == "\t" or ch == "\n"

    def is_alpha(ch: str) -> bool:
        return "a" <= ch <= "z" or "A" <= ch <= "Z"

    def is_digit(ch: str) -> bool:
        return "0" <= ch <= "9"

    while i < n:
        ch = src[i]
        if is_whitespace(ch):
            i += 1
            continue

        if is_digit(ch):
            j = i
            while j < n and is_digit(src[j]):
                j += 1
            if j < n:
                nxt = src[j]
                if nxt in NAME_START or nxt == "_" or nxt == "'":
                    raise SyntaxError_
            tokens.append(Token("int", src[i:j]))
            i = j
            continue

        if ch in NAME_START:
            j = i + 1
            while j < n and src[j] in NAME_CONT:
                j += 1
            text = src[i:j]
            if text in RESERVED:
                tokens.append(Token(text, text))
            else:
                tokens.append(Token("name", text))
            i = j
            continue

        two = src[i:i + 2]
        if two == "->":
            tokens.append(Token("->", "->"))
            i += 2
            continue
        if two == "::":
            tokens.append(Token("::", "::"))
            i += 2
            continue

        if ch == "(" or ch == ")" or ch == "," or ch == "+" or ch == "-" or ch == "*" or ch == "=" or ch == "<" or ch == "[" or ch == "]":
            tokens.append(Token(ch, ch))
            i += 1
            continue

        raise SyntaxError_

    return tokens


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Token]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self) -> Token:
        tok = self.peek()
        if tok is None:
            raise SyntaxError_
        self.pos += 1
        return tok

    def expect(self, kind: str) -> Token:
        tok = self.advance()
        if tok.kind != kind:
            raise SyntaxError_
        return tok

    def is_kw(self, kind: str) -> bool:
        tok = self.peek()
        return tok is not None and tok.kind == kind

    def is_op(self, kinds: set[str]) -> bool:
        tok = self.peek()
        return tok is not None and tok.kind in kinds

    def parse_program(self):
        e = self.parse_full()
        if self.peek() is not None:
            raise SyntaxError_
        return e

    def parse_full(self):
        tok = self.peek()
        if tok is None:
            raise SyntaxError_
        if tok.kind == "fun":
            return self.parse_fun()
        if tok.kind == "let":
            return self.parse_let()
        if tok.kind == "if":
            return self.parse_if()
        return self.parse_comparison()

    def parse_fun(self):
        self.advance()
        params = []
        while self.is_kw("name"):
            params.append(self.advance().text)
        if not params:
            raise SyntaxError_
        self.expect("->")
        body = self.parse_full()
        return ("fun", params, body)

    def parse_let(self):
        self.advance()
        rec = False
        if self.is_kw("rec"):
            self.advance()
            rec = True

        if not self.is_kw("name"):
            raise SyntaxError_
        name_tok = self.advance()
        name = name_tok.text

        params = []
        while self.is_kw("name"):
            params.append(self.advance().text)

        self.expect("=")
        body = self.parse_full()
        self.expect("in")
        rest = self.parse_full()
        return ("let", rec, name, params, body, rest)

    def parse_if(self):
        self.advance()
        cond = self.parse_comparison()
        self.expect("then")
        then = self.parse_full()
        self.expect("else")
        else_ = self.parse_full()
        return ("if", cond, then, else_)

    def parse_comparison(self):
        left = self.parse_cons()
        ops = []
        while self.is_op({"=", "<"}):
            op = self.advance().kind
            right = self.parse_cons()
            ops.append((op, right))
        if not ops:
            return left
        return ("chain", "=", ops, left) if False else self._make_left_chain(ops, left)

    def parse_cons(self):
        left = self.parse_additive()
        if self.is_op({"::"}):
            elements = [left]
            while self.is_op({"::"}):
                self.advance()
                # For right-associative ::, parse the tail at the same precedence.
                tail = self.parse_cons_operand()
                elements.append(tail)
            return ("cons_chain", elements)
        return left

    def parse_cons_operand(self):
        # A right operand of :: can itself be a cons chain, but it cannot be
        # an unparenthesized let/fun/if except through parentheses handled below.
        tok = self.peek()
        if tok is None:
            raise SyntaxError_
        if tok.kind == "(" :
            return self.parse_paren_or_tuple()
        return self.parse_additive()

    def parse_additive(self):
        left = self.parse_multiplicative()
        ops = []
        while self.is_op({"+", "-"}):
            op = self.advance().kind
            right = self.parse_multiplicative()
            ops.append((op, right))
        if not ops:
            return left
        return self._make_left_chain(ops, left)

    def parse_multiplicative(self):
        left = self.parse_application()
        ops = []
        while self.is_op({"*"}):
            op = self.advance().kind
            right = self.parse_application()
            ops.append((op, right))
        if not ops:
            return left
        return self._make_left_chain(ops, left)

    def parse_application(self):
        func = self.parse_primary()
        args = []
        while True:
            tok = self.peek()
            if tok is None:
                break
            if tok.kind == "name" or tok.kind in {"true", "false"} or tok.kind == "int" or tok.kind == "[":
                args.append(self.parse_primary())
            elif tok.kind == "(":
                args.append(self.parse_paren_or_tuple())
            else:
                break
        if not args:
            return func
        return ("app", func, args)

    def parse_primary(self):
        tok = self.peek()
        if tok is None:
            raise SyntaxError_

        if tok.kind == "int":
            return ("int", int(tok.text))
        if tok.kind == "true":
            return ("bool", True)
        if tok.kind == "false":
            return ("bool", False)
        if tok.kind == "name":
            self.advance()
            return ("name", tok.text)

        if tok.kind == "[":
            self.advance()
            self.expect("]")
            return ("nil",)

        if tok.kind == "(":
            return self.parse_paren_or_tuple()

        raise SyntaxError_

    def parse_paren_or_tuple(self):
        self.expect("(")
        first = self.parse_full()
        if self.is_op({")"}):
            self.advance()
            return first
        if self.is_op({","}):
            self.advance()
            second = self.parse_full()
            self.expect(")")
            return ("tuple", first, second)
        raise SyntaxError_

    def _make_left_chain(self, ops, first):
        # ops is [(op, right), ...] for left-associative binary operators.
        return ("left_chain", first, ops)


class TVar:
    __slots__ = ("ref", "level", "id")

    _counter = 0

    def __init__(self, level: int):
        self.ref = None
        self.level = level
        self.id = TVar._counter
        TVar._counter += 1


class TCon:
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name


class TFun:
    __slots__ = ("left", "right")

    def __init__(self, left, right):
        self.left = left
        self.right = right


class TTuple:
    __slots__ = ("left", "right")

    def __init__(self, left, right):
        self.left = left
        self.right = right


class TList:
    __slots__ = ("inner",)

    def __init__(self, inner):
        self.inner = inner


class TGen:
    __slots__ = ("id",)

    def __init__(self, id: int):
        self.id = id


def find(t):
    if isinstance(t, TVar):
        chain = []
        cur = t
        while True:
            if cur.ref is None:
                root = cur
                break
            nxt = cur.ref
            if isinstance(nxt, TVar):
                chain.append(cur)
                cur = nxt
                continue
            root = nxt
            break

        if isinstance(root, TVar):
            for v in chain:
                v.ref = root
        else:
            for v in chain:
                v.ref = root
        return root
    return t


def is_var_type(t) -> bool:
    return isinstance(t, TVar)


def fresh(level: int) -> TVar:
    return TVar(level)


def occurs_var(v: TVar, t, seen_vars=None, seen_nodes=None) -> bool:
    if seen_vars is None:
        seen_vars = set()
        seen_nodes = set()

    if isinstance(t, TVar):
        if t.id in seen_vars:
            return False
        seen_vars.add(t.id)
        r = find(t)
        if isinstance(r, TVar):
            if r.id == v.id:
                return True
            if r.id in seen_vars:
                return False
            seen_vars.add(r.id)
            return False
        if id(r) in seen_nodes:
            return False
        seen_nodes.add(id(r))
        return occurs_var_in_node(v, r, seen_vars, seen_nodes)

    if id(t) in seen_nodes:
        return False
    seen_nodes.add(id(t))
    return occurs_var_in_node(v, t, seen_vars, seen_nodes)


def occurs_var_in_node(v: TVar, node, seen_vars, seen_nodes) -> bool:
    if isinstance(node, TCon) or isinstance(node, TGen):
        return False
    if isinstance(node, TList):
        return occurs_var(v, node.inner, seen_vars, seen_nodes)
    if isinstance(node, TFun):
        return occurs_var(v, node.left, seen_vars, seen_nodes) or occurs_var(v, node.right, seen_vars, seen_nodes)
    if isinstance(node, TTuple):
        return occurs_var(v, node.left, seen_vars, seen_nodes) or occurs_var(v, node.right, seen_vars, seen_nodes)
    return False


def lower(t, new_level: int, seen_vars=None, seen_nodes=None):
    if seen_vars is None:
        seen_vars = set()
        seen_nodes = set()

    if isinstance(t, TVar):
        if t.id in seen_vars:
            return
        seen_vars.add(t.id)
        r = find(t)
        if isinstance(r, TVar):
            if r.id in seen_vars:
                return
            seen_vars.add(r.id)
            if r.level > new_level:
                r.level = new_level
            return
        if id(r) in seen_nodes:
            return
        seen_nodes.add(id(r))
        lower_node(r, new_level, seen_vars, seen_nodes)
        return

    if id(t) in seen_nodes:
        return
    seen_nodes.add(id(t))
    lower_node(t, new_level, seen_vars, seen_nodes)


def lower_node(node, new_level: int, seen_vars, seen_nodes):
    if isinstance(node, TCon) or isinstance(node, TGen):
        return
    if isinstance(node, TList):
        lower(node.inner, new_level, seen_vars, seen_nodes)
        return
    if isinstance(node, TFun):
        lower(node.left, new_level, seen_vars, seen_nodes)
        lower(node.right, new_level, seen_vars, seen_nodes)
        return
    if isinstance(node, TTuple):
        lower(node.left, new_level, seen_vars, seen_nodes)
        lower(node.right, new_level, seen_vars, seen_nodes)
        return


def unify(a, b):
    a = find(a)
    b = find(b)
    if a is b:
        return

    if isinstance(a, TVar) and isinstance(b, TVar):
        if a.level < b.level:
            b.ref = a
            if a.level > b.level:
                a.level = b.level
        elif b.level < a.level:
            a.ref = b
            if b.level > a.level:
                b.level = a.level
        else:
            b.ref = a
        return

    if isinstance(a, TVar):
        if occurs_var(a, b):
            raise TypeError("recursive type")
        a.ref = b
        lower(b, a.level)
        return

    if isinstance(b, TVar):
        if occurs_var(b, a):
            raise TypeError("recursive type")
        b.ref = a
        lower(a, b.level)
        return

    if isinstance(a, TCon) and isinstance(b, TCon):
        if a.name != b.name:
            raise TypeError("type mismatch")
        return

    if isinstance(a, TList) and isinstance(b, TList):
        unify(a.inner, b.inner)
        return

    if isinstance(a, TFun) and isinstance(b, TFun):
        unify(a.left, b.left)
        unify(a.right, b.right)
        return

    if isinstance(a, TTuple) and isinstance(b, TTuple):
        unify(a.left, b.left)
        unify(a.right, b.right)
        return

    raise TypeError("type mismatch")


def instantiate(t, level: int):
    cache = {}

    def inst(node):
        if isinstance(node, TGen):
            v = cache.get(node.id)
            if v is None:
                v = fresh(level)
                cache[node.id] = v
            return v

        if isinstance(node, TVar):
            return node

        if isinstance(node, TCon):
            return node

        if isinstance(node, TList):
            return TList(inst(node.inner))

        if isinstance(node, TFun):
            return TFun(inst(node.left), inst(node.right))

        if isinstance(node, TTuple):
            return TTuple(inst(node.left), inst(node.right))

        raise TypeError("internal type error")

    return inst(t)


def generalize(t, level: int):
    mono_cache = {}
    gen_cache = {}

    def gen_node(node):
        if isinstance(node, TGen):
            return node

        if isinstance(node, TCon):
            return node

        if isinstance(node, TList):
            return TList(gen_node(node.inner))

        if isinstance(node, TFun):
            return TFun(gen_node(node.left), gen_node(node.right))

        if isinstance(node, TTuple):
            return TTuple(gen_node(node.left), gen_node(node.right))

        if isinstance(node, TVar):
            r = find(node)
            if isinstance(r, TVar):
                key = r.id
                if key in mono_cache:
                    return mono_cache[key]
                if key in gen_cache:
                    return gen_cache[key]

                if r.level > level:
                    g = TGen(len(gen_cache) + 1)
                    gen_cache[key] = g
                    return g
                else:
                    # Keep one representative variable object for all occurrences.
                    rep = r
                    mono_cache[key] = rep
                    return rep

            return gen_node(r)

        raise TypeError("internal type error")

    return gen_node(t)


def env_find(env: dict, name: str):
    try:
        return env[name]
    except KeyError:
        raise NameError(name)


def make_base_env():
    a = fresh(0)
    b = fresh(0)
    return {
        "fst": TFun(TTuple(a, b), a),
        "snd": TFun(TTuple(a, b), b),
        "hd": TList(a),
        "tl": TFun(TList(a), TList(a)),
        "null": TFun(TList(a), TCon("bool")),
    }


def instantiate_env_binding(env, name, level):
    t = env_find(env, name)
    return instantiate(t, level)


def infer_ast(ast, env: dict, level: int):
    kind = ast[0]

    if kind == "int":
        return TCon("int")

    if kind == "bool":
        return TCon("bool")

    if kind == "nil":
        return TList(fresh(level))

    if kind == "name":
        return instantiate_env_binding(env, ast[1], level)

    if kind == "tuple":
        left = infer_ast(ast[1], env, level)
        right = infer_ast(ast[2], env, level)
        return TTuple(left, right)

    if kind == "fun":
        params = ast[1]
        body = ast[2]
        env2 = dict(env)
        cur = fresh(level)
        for name in reversed(params):
            var = fresh(level)
            cur = TFun(var, cur)
            env2[name] = cur.right
        body_type = infer_ast(body, env2, level)
        # Reconstruct arrow left-associatively from parameter list.
        result = body_type
        for name in reversed(params):
            result = TFun(env2[name], result)
        return result

    if kind == "app":
        func_type = infer_ast(ast[1], env, level)
        args = ast[2]
        cur = func_type
        for arg_ast in args:
            arg_type = infer_ast(arg_ast, env, level)
            result = fresh(level)
            unify(cur, TFun(arg_type, result))
            cur = result
        return cur

    if kind == "left_chain":
        left = ast[1]
        ops = ast[2]
        cur = infer_ast(left, env, level)
        for op, right_ast in ops:
            right = infer_ast(right_ast, env, level)
            if op in {"+", "-", "*"}:
                result = TCon("int")
                unify(cur, TCon("int"))
                unify(right, TCon("int"))
                cur = result
            elif op in {"=", "<"}:
                if op == "=":
                    a = fresh(level)
                    unify(cur, a)
                    unify(right, a)
                    cur = TCon("bool")
                else:
                    unify(cur, TCon("int"))
                    unify(right, TCon("int"))
                    cur = TCon("bool")
            else:
                raise TypeError("internal operator")
        return cur

    if kind == "cons_chain":
        elems = ast[1]
        res = infer_ast(elems[-1], env, level)
        for elem_ast in reversed(elems[:-1]):
            elem_type = infer_ast(elem_ast, env, level)
            item = fresh(level)
            unify(res, TList(item))
            unify(elem_type, item)
            res = TList(item)
        return res

    if kind == "if":
        cond = ast[1]
        then = ast[2]
        else_ = ast[3]
        c = infer_ast(cond, env, level)
        unify(c, TCon("bool"))
        a = infer_ast(then, env, level)
        b = infer_ast(else_, env, level)
        unify(a, b)
        return a

    if kind == "let":
        rec, name, params, body, rest = ast[1], ast[2], ast[3], ast[4], ast[5]
        # If a let binding has parameters, it is sugar for let name = fun ... in rest.
        if params:
            body = ("fun", params, body)

        if not rec:
            env_body = dict(env)
            var = fresh(level + 1)
            env_body[name] = var
            body_type = infer_ast(body, env_body, level + 1)
            unify(var, body_type)
            generalized = generalize(var, level)
            env_after = dict(env)
            env_after[name] = generalized
            return infer_ast(rest, env_after, level)

        # let rec: monomorphic type inside the body, generalized after the body.
        env_body = dict(env)
        fvar = fresh(level + 1)
        cur = fresh(level + 1)
        for name2 in reversed(params):
            pvar = fresh(level + 1)
            cur = TFun(pvar, cur)
            env_body[name2] = cur.right

        env_body[name] = TFun(
            env_body[params[0]] if False else cur.left,
            cur.right
        ) if False else cur

        # Reconstruct the monomorphic function type correctly.
        mono_func = body = None
        cur = cur
        for name2 in reversed(params):
            cur = TFun(env_body[name2], cur)
        mono_func = cur

        env_body[name] = mono_func
        body_type = infer_ast(body, env_body, level + 1)
        unify(mono_func, body_type)

        generalized = generalize(mono_func, level)
        env_after = dict(env)
        env_after[name] = generalized
        return infer_ast(rest, env_after, level)

    raise TypeError("internal AST error")


def format_type(t, counter):
    if isinstance(t, TVar):
        r = find(t)
        if isinstance(r, TVar):
            key = r.id
            name = counter.get(key)
            if name is None:
                name = name_for_index(counter.count)
                counter[key] = name
                counter.count += 1
            return name
        return format_type(r, counter)

    if isinstance(t, TCon):
        return t.name

    if isinstance(t, TList):
        inner = format_type(t.inner, counter)
        if isinstance(t.inner, TFun) or isinstance(t.inner, TTuple):
            inner = "(" + inner + ")"
        return inner + " list"

    if isinstance(t, TFun):
        left = format_type(t.left, counter)
        right = format_type(t.right, counter)
        if isinstance(t.left, TFun):
            left = "(" + left + ")"
        if isinstance(t.left, TTuple):
            left = "(" + left + ")"
        return left + " -> " + right

    if isinstance(t, TTuple):
        left = format_type(t.left, counter)
        right = format_type(t.right, counter)
        if isinstance(t.left, TFun):
            left = "(" + left + ")"
        if isinstance(t.left, TTuple):
            left = "(" + left + ")"
        if isinstance(t.right, TFun):
            right = "(" + right + ")"
        if isinstance(t.right, TTuple):
            right = "(" + right + ")"
        return left + " * " + right

    raise TypeError("internal type formatting error")


def name_for_index(i: int) -> str:
    base = []
    while True:
        q, r = divmod(i, 26)
        base.append(chr(ord("a") + r))
        i = q - 1 if q > 0 else q
        if q == 0:
            break
    return "'" + "".join(reversed(base))


def infer(src: str) -> str:
    if not isinstance(src, str):
        raise SyntaxError_

    tokens = tokenize(src)
    if not tokens:
        raise SyntaxError_

    parser = Parser(tokens)
    ast = parser.parse_program()

    # Syntax errors must be reported before semantic errors.
    env = make_base_env()
    result = infer_ast(ast, env, 0)

    counter = {"count": 0}
    return format_type(result, counter)
